<script setup lang="ts">
import { computed,nextTick,reactive,ref } from 'vue';
import { Head,router } from '@inertiajs/vue3';
import { t } from '../../i18n';
import { formatMoney,majorAmount,type CurrencyPreferences } from '../../business-money';
import { useBusinessMutation } from '../../use-business-mutation';
import OperationFeedback from '../../components/OperationFeedback.vue';
import NumericInput from '../../components/NumericInput.vue';
import WorkspaceIcon from '../../components/WorkspaceIcon.vue';
type Product={product_id:string;sku:string;display_name:string;category:string;brand:string;variant:string;barcode:string;unit_price_atomic:string;cost_atomic:string;wholesale_atomic:string;available_quantity:string;currency:string;currency_scale:number;version:number;active:boolean;stock_ready:boolean;stock_mode?:'tracked'|'unlimited'};
const props=defineProps<{products:{data:Product[];page:number;has_more:boolean;total:number;categories:string[];brands:string[]};filters:Record<string,string>;preferences:CurrencyPreferences}>();
const filters=reactive({q:props.filters.q??'',category:props.filters.category??'',brand:props.filters.brand??'',status:props.filters.status??''});
const tab=ref('products');const dialog=ref<HTMLDialogElement|null>(null);const importDialog=ref<HTMLDialogElement|null>(null);const editing=ref<Product|null>(null);
const categoryDialog=ref<HTMLDialogElement|null>(null);const categoryName=ref('');
const form=reactive({stock_mode:'tracked',sku:'',name:'',category:'',brand:'',variant:'',barcode:'',price:'0',cost:'0',wholesale:'0',opening_quantity:'0',active:true});
const {busy,uncertain,error,status,operationId,submit,clear}=useBusinessMutation();const scale=computed(()=>editing.value?.currency_scale??Number(props.preferences.scale));
const importFile=ref<File|null>(null);const preview=ref<any|null>(null);const previewBusy=ref(false);const previewError=ref('');const success=ref('');
function navigate(page=1):void {router.get('/pos/business/products',{...filters,page},{preserveScroll:true});}
const query=computed(()=>new URLSearchParams(Object.entries(props.filters)).toString());
function open(p:Product|null=null):void {if(uncertain.value)return;clear();editing.value=p;Object.assign(form,{stock_mode:p?.stock_mode??'tracked',sku:p?.sku??'',name:p?.display_name??'',category:p?.category??'',brand:p?.brand??'',variant:p?.variant??'',barcode:p?.barcode??'',price:majorAmount(p?.unit_price_atomic??'0',p?.currency_scale??Number(props.preferences.scale)),cost:majorAmount(p?.cost_atomic??'0',p?.currency_scale??Number(props.preferences.scale)),wholesale:majorAmount(p?.wholesale_atomic??'0',p?.currency_scale??Number(props.preferences.scale)),opening_quantity:'0',active:p?.active??true});nextTick(()=>dialog.value?.showModal());}
async function save():Promise<void>{const v=await submit('/pos/business/products/save',{...form,opening_quantity:form.stock_mode==='unlimited'?'0':form.opening_quantity,...(editing.value?{product_id:editing.value.product_id,version:editing.value.version}:{})});if(v){dialog.value?.close();success.value=t('Product saved.');router.reload();}}
function addCategory():void {if(busy.value||uncertain.value)return;clear();categoryName.value='';categoryDialog.value?.showModal();}
async function saveCategory():Promise<void>{const v=await submit('/pos/business/products/categories',{name:categoryName.value});if(v){categoryDialog.value?.close();success.value=t('Category saved.');router.reload({only:['products']});}}
function close(which:HTMLDialogElement|null):void {if(!busy.value&&!uncertain.value&&!previewBusy.value)which?.close();}
function startImport():void{if(uncertain.value)return;clear();preview.value=null;previewError.value='';importFile.value=null;importDialog.value?.showModal();}
function choose(event:Event):void{importFile.value=(event.target as HTMLInputElement).files?.[0]??null;preview.value=null;previewError.value='';}
async function inspect():Promise<void>{if(!importFile.value)return;previewBusy.value=true;previewError.value='';preview.value=null;try{if(importFile.value.size>2000000)throw new Error(t('Maximum file size: 2 MB.'));const data=new FormData();data.append('file',importFile.value);const token=document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??'';const response=await fetch('/pos/business/products/import/preview',{method:'POST',credentials:'same-origin',redirect:'error',headers:{Accept:'application/json','X-CSRF-TOKEN':token},body:data});const result=await response.json();if(!response.ok)throw new Error(t(result.error?.code??result.message??'Could not read the import file.'));preview.value=result;}catch(e){previewError.value=e instanceof Error?e.message:t('Could not read the import file.');}finally{previewBusy.value=false;}}
async function commit():Promise<void>{if(!preview.value?.can_commit)return;const p=preview.value;const v=await submit('/pos/business/products/import/commit',{rows:p.source_rows,preview_digest:p.preview_digest,settings_version:p.settings_version});if(v){success.value=`${v.imported} ${t('products imported successfully.')}`;importDialog.value?.close();router.reload();}}
</script>
<template>
<Head :title="t('Product catalog')"/>
<main class="merch-page"><OperationFeedback :status="status" :message="error" :operation-id="operationId"/>
 <header class="merch-heading"><div><p class="eyebrow">{{ t('Products & inventory') }}</p><h1>{{ t('Product catalog') }}</h1><p>{{ t('Manage sale products, prices, categories, and opening stock.') }}</p></div><div class="merch-actions"><button class="secondary" @click="addCategory"><WorkspaceIcon name="plus" :size="16"/>{{ t('Add category') }}</button><button class="secondary" @click="startImport"><WorkspaceIcon name="upload" :size="16"/>{{ t('Import products') }}</button><button @click="open()">+ {{ t('Add product') }}</button></div></header>
 <p v-if="success" class="merch-success" role="status">{{ success }}</p>
 <nav class="merch-tabs" :aria-label="t('Catalog sections')"><button v-for="item in ['products','categories','brands']" :key="item" :class="{active:tab===item}" :aria-current="tab===item?'page':undefined" @click="tab=item">{{ t({products:'Products',categories:'Categories',brands:'Brands'}[item]) }}</button><a href="/pos/catalog-inventory/setup">{{ t('Opening stock') }}</a><a href="/pos/inventory/replenishment">{{ t('Receive stock') }}</a></nav>
 <section class="merch-panel">
  <form class="merch-toolbar" @submit.prevent="navigate()"><label class="merch-search"><WorkspaceIcon name="search" :size="17"/><input v-model="filters.q" type="search" :placeholder="t('Search product name, SKU or barcode')" :aria-label="t('Search products')"/></label><select v-model="filters.category" :aria-label="t('Category')"><option value="">{{ t('All categories') }}</option><option v-for="c in products.categories" :key="c">{{ c }}</option></select><select v-model="filters.brand" :aria-label="t('Brand')"><option value="">{{ t('All brands') }}</option><option v-for="b in products.brands" :key="b">{{ b }}</option></select><select v-model="filters.status" :aria-label="t('Status')"><option value="">{{ t('All statuses') }}</option><option value="active">{{ t('Active') }}</option><option value="inactive">{{ t('Inactive') }}</option></select><button type="submit">{{ t('Apply') }}</button></form>
  <div class="merch-subtoolbar"><span>{{ products.total }} {{ t('products') }} · {{ t('Prices follow each product currency.') }}</span><div><a :href="`/pos/business/reports/products/download?format=xlsx&${query}`">{{ t('Download Excel') }}</a><a :href="`/pos/business/reports/products/download?format=pdf&${query}`">{{ t('Download PDF') }}</a></div></div>
  <div v-if="tab==='products'" class="merch-table-wrap"><table class="merch-table"><thead><tr><th>{{ t('Product') }}</th><th>SKU / {{ t('Barcode') }}</th><th>{{ t('Category') }}</th><th>{{ t('Brand / variant') }}</th><th class="numeric">{{ t('Stock') }}</th><th class="numeric">{{ t('Cost price') }}</th><th class="numeric">{{ t('Selling price') }}</th><th class="numeric">{{ t('Wholesale price') }}</th><th>{{ t('Status') }}</th><th>{{ t('Actions') }}</th></tr></thead><tbody><tr v-for="p in products.data" :key="p.product_id"><td><div class="merch-product"><span class="merch-product-icon"><WorkspaceIcon name="package"/></span><div><button class="link-button" @click="open(p)">{{ p.display_name }}</button><small>{{ p.product_id }}</small></div></div></td><td><strong>{{ p.sku }}</strong><small>{{ p.barcode||'—' }}</small></td><td>{{ p.category||'—' }}</td><td>{{ p.brand||'—' }}<small>{{ p.variant }}</small></td><td class="numeric"><span v-if="p.stock_mode==='unlimited'" class="stock-mode-pill">∞ {{t('Unlimited')}}</span><template v-else>{{ p.available_quantity }}<small v-if="!p.stock_ready">{{ t('Opening stock required') }}</small></template></td><td class="numeric">{{ formatMoney(p.cost_atomic,p.currency,p.currency_scale) }}</td><td class="numeric">{{ formatMoney(p.unit_price_atomic,p.currency,p.currency_scale) }}</td><td class="numeric">{{ formatMoney(p.wholesale_atomic,p.currency,p.currency_scale) }}</td><td><span class="merch-badge" :class="{inactive:!p.active}">{{ t(p.active?'Active':'Inactive') }}</span></td><td><button class="link-button" @click="open(p)">{{ t('Edit') }}</button></td></tr><tr v-if="!products.data.length"><td colspan="10" class="merch-empty"><WorkspaceIcon name="package" :size="40"/><h2>{{ t('No products found') }}</h2><p>{{ t('Add a product or import your product list.') }}</p></td></tr></tbody></table></div>
  <div v-else class="merch-directory"><article v-if="tab==='categories'" class="category-create-card"><WorkspaceIcon name="plus"/><h3>{{t('Create a product category')}}</h3><p>{{t('Organize your catalog before adding products.')}}</p><button @click="addCategory">{{t('Add category')}}</button></article><article v-for="name in tab==='categories'?products.categories:products.brands" :key="name"><WorkspaceIcon name="package"/><h3>{{ name }}</h3><button class="secondary" @click="tab==='categories'?filters.category=name:filters.brand=name;navigate()">{{ t('View products') }}</button></article><p v-if="!(tab==='categories'?products.categories:products.brands).length">{{ t('Enter a category or brand when adding products.') }}</p></div>
  <footer class="merch-pagination"><span>{{ t('Page') }} {{ products.page }} · 50 {{ t('rows per page') }}</span><div><button class="secondary" :disabled="products.page<=1" @click="navigate(products.page-1)">{{ t('Previous') }}</button><button class="secondary" :disabled="!products.has_more" @click="navigate(products.page+1)">{{ t('Next') }}</button></div></footer>
 </section>
 <dialog ref="dialog" class="merch-dialog" @cancel.prevent="close(dialog)"><form @submit.prevent="save"><header><div><h2>{{ t(editing?'Edit product':'Add product') }}</h2><p>{{ t('Currency') }}: {{ editing?.currency??preferences.currency }} · {{ scale }} {{ t('decimal places') }}</p></div><button type="button" class="link-button" :aria-label="t('Close')" @click="close(dialog)">×</button></header><fieldset :disabled="busy||uncertain"><div class="merch-form-grid"><label>SKU<input v-model="form.sku" required maxlength="64" :readonly="!!editing" pattern="[A-Za-z0-9]([A-Za-z0-9_-]*[A-Za-z0-9])?"/></label><label>{{ t('Product name') }}<input v-model="form.name" required maxlength="160"/></label><label>{{ t('Category') }}<input v-model="form.category" list="catalog-categories" maxlength="120"/><datalist id="catalog-categories"><option v-for="c in products.categories" :key="c">{{ c }}</option></datalist></label><label>{{ t('Brand') }}<input v-model="form.brand" list="catalog-brands" maxlength="120"/><datalist id="catalog-brands"><option v-for="b in products.brands" :key="b">{{ b }}</option></datalist></label><label>{{ t('Variant') }}<input v-model="form.variant" maxlength="120"/></label><label>{{ t('Barcode') }}<input v-model="form.barcode" maxlength="64"/></label><label>{{ t('Selling price') }}<NumericInput v-model="form.price" :decimals="scale"/></label><label>{{ t('Cost price') }}<NumericInput v-model="form.cost" :decimals="scale"/></label><label>{{ t('Wholesale price') }}<NumericInput v-model="form.wholesale" :decimals="scale"/></label><label>{{t('Stock management')}}<select v-model="form.stock_mode" :aria-label="t('Stock management')"><option value="tracked">{{t('Track stock')}}</option><option value="unlimited">{{t('Unlimited stock')}}</option></select></label><p class="stock-mode-help">{{t(form.stock_mode==='unlimited'?'Unlimited products remain sellable without reducing stock.':'Sales reduce available stock and stop when stock is insufficient.')}}</p><label v-if="!editing&&form.stock_mode==='tracked'">{{ t('Opening quantity') }}<NumericInput v-model="form.opening_quantity"/></label><label class="merch-check"><input v-model="form.active" type="checkbox"/>{{ t('Active and sellable') }}</label></div></fieldset><p class="merch-hint">{{ t('Use digits and a decimal point; do not use thousands separators.') }}</p><p v-if="editing" class="merch-hint">{{ t('Receive additional stock through Inventory. Existing opening stock is preserved.') }}</p><p v-if="error" class="merch-error" role="alert">{{ error }}</p><footer><button type="button" class="secondary" :disabled="busy||uncertain" @click="close(dialog)">{{ t('Cancel') }}</button><button :disabled="busy">{{ t(busy?'Saving…':uncertain?'Retry same request':'Save product') }}</button></footer></form></dialog>
 <dialog ref="categoryDialog" class="merch-dialog category-dialog" @cancel.prevent="close(categoryDialog)"><form @submit.prevent="saveCategory"><header><div><h2>{{t('Add category')}}</h2><p>{{t('Organize your catalog before adding products.')}}</p></div><button type="button" class="link-button" :aria-label="t('Close')" :disabled="busy||uncertain" @click="close(categoryDialog)">×</button></header><fieldset :disabled="busy||uncertain"><label>{{t('Category name')}}<input v-model="categoryName" required maxlength="120" autofocus :placeholder="t('Example: Drinks, Food, Services')"/></label></fieldset><p v-if="error" class="merch-error" role="alert">{{error}}</p><footer><button type="button" class="secondary" :disabled="busy||uncertain" @click="close(categoryDialog)">{{t('Cancel')}}</button><button :disabled="busy">{{t(busy?'Saving…':uncertain?'Retry same request':'Save category')}}</button></footer></form></dialog>
 <dialog ref="importDialog" class="merch-dialog import-dialog" @cancel.prevent="close(importDialog)"><div class="merch-dialog-body"><header><div><h2>{{ t('Import products') }}</h2><p>{{ t('CSV or Excel (.xlsx), maximum 500 products per file.') }}</p></div><button type="button" class="link-button" :aria-label="t('Close')" @click="close(importDialog)">×</button></header><ol class="import-steps"><li><a href="/pos/business/products/import/template">{{ t('Download Excel template') }}</a></li><li>{{ t('Fill every numeric field with digits. Use a decimal point for prices.') }}</li><li>{{ t('Preview and correct every error before importing.') }}</li></ol><p class="merch-hint">{{ t('New products only. Existing products and opening stock are never overwritten by import.') }} {{ t('Currency') }}: {{ preferences.currency }} ({{ preferences.symbol }})</p><label class="import-drop"><WorkspaceIcon name="upload" :size="28"/><strong>{{ t('Choose product file') }}</strong><input type="file" accept=".csv,.xlsx" :disabled="busy||uncertain||previewBusy" @change="choose"/><span>{{ importFile?.name??t('Maximum file size: 2 MB.') }}</span></label><p v-if="previewError||error" class="merch-error" role="alert">{{ previewError||error }}</p><section v-if="preview"><h3>{{ preview.count }} {{ t('rows inspected') }} · {{ preview.errors.length }} {{ t('errors') }}</h3><div v-if="preview.errors.length" class="import-errors"><p v-for="e in preview.errors" :key="e.row">{{ t('Row') }} {{ e.row }}: {{ t(e.code) }}</p></div><div v-else class="merch-table-wrap"><table class="merch-table"><thead><tr><th>SKU</th><th>{{ t('Product') }}</th><th>{{ t('Selling price') }}</th><th>{{ t('Opening quantity') }}</th></tr></thead><tbody><tr v-for="p in preview.rows.slice(0,20)" :key="p.product_id"><td>{{ p.sku }}</td><td>{{ p.display_name }}</td><td>{{ formatMoney(p.unit_price_atomic,p.currency,p.currency_scale) }}</td><td>{{ p.opening_quantity }}</td></tr></tbody></table><p>{{ t('Preview shows the first 20 rows. All validated rows will be imported.') }}</p></div></section><footer><button class="secondary" :disabled="busy||uncertain||previewBusy" @click="close(importDialog)">{{ t('Cancel') }}</button><button v-if="!preview?.can_commit" :disabled="!importFile||previewBusy||busy" @click="inspect">{{ t(previewBusy?'Reading file…':'Preview import') }}</button><button v-else :disabled="busy" @click="commit">{{ t(busy?'Importing…':uncertain?'Retry same request':'Import all valid products') }}</button></footer></div></dialog>
</main>
</template>
